1	"use client";
2	
3	import { memo, useState } from "react";
4	import type { ToolData, ToolPeek, AskQuestion, AskAnswers } from "@/lib/types";
5	import { Icon } from "../icons";
6	import { Markdown } from "../Markdown";
7	import { diffCls, splitAttachments, type MsgAttachment } from "./format";
8	import { CONTEXT_OVERFLOW_NOTICE } from "@/lib/promptLimits";
9	import { AUTH_EXPIRED_NOTICE } from "@/lib/authFailure";
10	import { USAGE_LIMIT_NOTICE } from "@/lib/usageLimit";
11	import type { Msg } from "./types";
12	import { Avatar } from "./shared";
13	import { CopyButton } from "../CopyButton";
14	import {
15	  ARTIFACT_NOTICE_PREFIX,
16	  decodeArtifactNotice,
17	  type ArtifactNotice,
18	} from "@/lib/artifactNotice";
19	
20	function MessageTime({ value }: { value?: number }) {
21	  if (!value) return null;
22	  const date = new Date(value);
23	  return (
24	    <time
25	      className="msg-time"
26	      dateTime={date.toISOString()}
27	      title={date.toLocaleString()}
28	    >
29	      {date.toLocaleString([], {
30	        month: "short",
31	        day: "numeric",
32	        hour: "numeric",
33	        minute: "2-digit",
34	      })}
35	    </time>
36	  );
37	}
38	
39	function ArtifactNoticeView({
40	  notice,
41	  createdAt,
42	}: {
43	  notice: ArtifactNotice;
44	  createdAt?: number;
45	}) {
46	  const absoluteUrl =
47	    typeof window === "undefined"
48	      ? notice.url
49	      : new URL(notice.url, window.location.origin).toString();
50	  return (
51	    <div className="msg artifact-msg">
52	      <div className="artifact-msg-head">
53	        <span className="artifact-type">Published artifact</span>
54	        <span className="msg-meta-spacer" />
55	        <MessageTime value={createdAt} />
56	      </div>
57	      <div className="artifact-msg-title">{notice.title}</div>
58	      <div className="artifact-msg-file">{notice.filename}</div>
59	      <div className="artifact-msg-actions">
60	        <a href={notice.url} target="_blank" rel="noreferrer">Open artifact</a>
61	        <CopyButton text={absoluteUrl} label="Copy link" />
62	        <a href={notice.libraryUrl}>View all artifacts</a>
63	      </div>
64	    </div>
65	  );
66	}
67	
68	// The always-visible "peek" tier — Claude Code's `⎿` line. Counts show no
69	// content; diffs/snippets show a capped hunk with a clickable "+N more" that
70	// opens the full body. TodoWrite renders its checklist inline.
71	function PeekView({ peek, expandable, onExpand }: { peek: ToolPeek; expandable: boolean; onExpand: () => void }) {
72	  const corner = <span className="tcorner">⎿</span>;
73	  if (peek.kind === "count") {
74	    return (
75	      <button className="tpeek tpeek-count" style={{ cursor: expandable ? "pointer" : "default" }} onClick={() => expandable && onExpand()}>
76	        {corner}<span className="tpeek-txt">{peek.text}</span>
77	        {expandable && <span className="tpeek-more">expand</span>}
78	      </button>
79	    );
80	  }
81	  if (peek.kind === "todos") {
82	    return (
83	      <div className="tpeek tpeek-todos">
84	        {peek.items.map((t, i) => (
85	          <div className={`tdo ${t.status}`} key={i}>
86	            <span className="tdo-box">{t.status === "completed" ? "✔" : t.status === "in_progress" ? "▣" : "▢"}</span>
87	            <span className="tdo-txt">{t.text}</span>
88	          </div>
89	        ))}
90	      </div>
91	    );
92	  }
93	  if (peek.kind === "diff") {
94	    return (
95	      <div className="tpeek tpeek-diff">
96	        <div className="tpeek-sum">{corner}<span className="dstat add">+{peek.added}</span><span className="dstat del">−{peek.removed}</span>{peek.label && <span className="tpeek-txt">{peek.label}</span>}</div>
97	        <pre className="tpeek-pre diff">{peek.lines.map((l, i) => <div className={`dl ${diffCls(l.sign)}`} key={i}>{l.sign} {l.text}</div>)}</pre>
98	        {peek.truncated ? <button className="tpeek-more btn-link" onClick={onExpand}>+{peek.truncated} more lines</button> : null}
99	      </div>
100	    );
101	  }
102	  // lines (Bash output)
103	  return (
104	    <div className="tpeek tpeek-lines">
105	      {peek.label && <div className="tpeek-sum">{corner}<span className="tpeek-txt">{peek.label}</span></div>}
106	      <pre className="tpeek-pre">{peek.lines.join("\n") || "(no output)"}</pre>
107	      {peek.truncated ? <button className="tpeek-more btn-link" onClick={onExpand}>+{peek.truncated} more lines</button> : null}
108	    </div>
109	  );
110	}
111	
112	function ToolView({ data, condensed }: { data: ToolData; condensed?: boolean }) {
113	  const [open, setOpen] = useState(false);
114	  const hasDiff = !!data.diff?.length;
115	  const expandable = !!(data.detail || hasDiff || data.result !== undefined);
116	  // Failures surface their output automatically, like Claude Code.
117	  const showBody = open || (!!data.isError && data.result !== undefined);
118	  // Older tool calls collapse to their one-line header so a long transcript
119	  // reads as prose; the peek tier only renders for the latest activity (or
120	  // errors, or anything the user explicitly opened).
121	  const showPeek = data.peek && !showBody && (!condensed || !!data.isError);
122	  return (
123	    <div className="tool">
124	      <button className="tool-h" style={{ cursor: expandable ? "pointer" : "default" }} onClick={() => expandable && setOpen((o) => !o)}>
125	        {expandable && <span className={`tchev ${showBody ? "open" : ""}`}>{Icon.chevRight()}</span>}
126	        <span className="tg">{data.title}</span>
127	        {data.result !== undefined && <span className={data.isError ? "tx" : "tcheck"}>{data.isError ? Icon.x() : Icon.check()}</span>}
128	      </button>
129	      {showPeek && <PeekView peek={data.peek!} expandable={expandable} onExpand={() => setOpen(true)} />}
130	      {showBody && (
131	        <div className="tool-body">
132	          {data.detail && <pre className="tool-pre">{data.detail}</pre>}
133	          {hasDiff && (
134	            <pre className="tool-pre diff">{data.diff!.map((l, i) => <div className={`dl ${diffCls(l.sign)}`} key={i}>{l.sign} {l.text}</div>)}</pre>
135	          )}
136	          {data.result !== undefined && (
137	            <>
138	              {(data.detail || hasDiff) && <div className="tool-divider">result</div>}
139	              <pre className={`tool-pre ${data.isError ? "err" : ""}`}>{data.result || "(no output)"}</pre>
140	            </>
141	          )}
142	        </div>
143	      )}
144	    </div>
145	  );
146	}
147	
148	// Interactive AskUserQuestion card: option pickers (+ an "Other" free-text per
149	// question) while pending; a read-only summary once answered.
150	function AskView({ data, agentLabel, onAnswer }: { data: ToolData; agentLabel: string; onAnswer: (answers: AskAnswers) => Promise<void> }) {
151	  const questions = data.ask?.questions ?? [];
152	  const existing = data.ask?.answers;
153	  const [state, setState] = useState(() => questions.map(() => ({ picked: [] as string[], other: "" })));
154	  const [submitted, setSubmitted] = useState(false);
155	  const [submitError, setSubmitError] = useState("");
156	
157	  if (existing) {
158	    return (
159	      <div className="ask answered">
160	        <div className="ask-head">{Icon.spark()} You answered</div>
161	        {questions.map((q, i) => (
162	          <div className="ask-q" key={i}>
163	            <div className="ask-qh"><span className="ask-chip">{q.header}</span>{q.question}</div>
164	            <div className="ask-picked">{(existing[i] ?? []).join(", ") || "—"}</div>
165	          </div>
166	        ))}
167	      </div>
168	    );
169	  }
170	
171	  const toggle = (qi: number, label: string, multi: boolean) =>
172	    setState((s) => s.map((st, i) => {
173	      if (i !== qi) return st;
174	      if (multi) {
175	        const has = st.picked.includes(label);
176	        return { ...st, picked: has ? st.picked.filter((l) => l !== label) : [...st.picked, label] };
177	      }
178	      return { picked: [label], other: "" }; // single-select replaces, clears Other
179	    }));
180	  const setOther = (qi: number, v: string) =>
181	    setState((s) => s.map((st, i) => (i === qi ? (questions[i].multiSelect ? { ...st, other: v } : { picked: [], other: v }) : st)));
182	
183	  const answers: AskAnswers = state.map((st) => [...st.picked, ...(st.other.trim() ? [st.other.trim()] : [])]);
184	  const complete = answers.every((a) => a.length > 0);
185	  const submit = async () => {
186	    if (!complete || submitted) return;
187	    setSubmitted(true);
188	    setSubmitError("");
189	    try {
190	      await onAnswer(answers);
191	    } catch {
192	      setSubmitted(false);
193	      setSubmitError("Your answer was not saved. Try again.");
194	    }
195	  };
196	
197	  return (
198	    <div className="ask">
199	      <div className="ask-head">{Icon.spark()} {agentLabel} needs your input</div>
200	      {questions.map((q, i) => (
201	        <div className="ask-q" key={i}>
202	          <div className="ask-qh"><span className="ask-chip">{q.header}</span>{q.question}{q.multiSelect && <span className="ask-multi">pick any</span>}</div>
203	          <div className="ask-opts">
204	            {q.options.map((o) => (
205	              <button key={o.label} className={`ask-opt ${state[i].picked.includes(o.label) ? "on" : ""}`} onClick={() => toggle(i, o.label, !!q.multiSelect)} disabled={submitted}>
206	                <span className="ask-opt-l">{o.label}</span>
207	                {o.description && <span className="ask-opt-d">{o.description}</span>}
208	              </button>
209	            ))}
210	            <input className="ask-other" placeholder="Other…" value={state[i].other} disabled={submitted} onChange={(e) => setOther(i, e.target.value)} />
211	          </div>
212	        </div>
213	      ))}
214	      <div className="ask-foot">
215	        {submitError && <span className="ask-submit-error" role="alert">{submitError}</span>}
216	        <button className="btn btn-accent btn-sm" onClick={() => void submit()} disabled={!complete || submitted}>{submitted ? "Sending…" : submitError ? "Retry answer" : "Send answer"}</button>
217	      </div>
218	    </div>
219	  );
220	}
221	
222	// Attachment chips parsed out of a user message's markers: image thumbnails
223	// (click opens full size) and text-file chips (a big paste diverted to a file;
224	// click opens it). Both are served from the task's uploads dir.
225	function AttachmentStrip({ items }: { items: MsgAttachment[] }) {
226	  if (!items.length) return null;
227	  return (
228	    <div className="msg-attachments">
229	      {items.map((a, i) =>
230	        a.kind === "image" ? (
231	          <a key={i} href={a.url} target="_blank" rel="noreferrer" title="Open full size">
232	            {/* eslint-disable-next-line @next/next/no-img-element */}
233	            <img src={a.url} alt="attached image" loading="lazy" />
234	          </a>
235	        ) : (
236	          <a key={i} href={a.url} target="_blank" rel="noreferrer" className="file-chip" title={`Open ${a.name}`}>
237	            {Icon.clip()} <span>attached file</span>
238	          </a>
239	        )
240	      )}
241	    </div>
242	  );
243	}
244	
245	// Memoized: during a live turn every SSE event re-renders the transcript's
246	// parents, but message objects are append-only (replaced only when their content
247	// changes), so unchanged messages skip re-rendering — and re-parsing their
248	// markdown — entirely. Callers must pass identity-stable handlers or the memo
249	// is defeated (SessionView wraps its handlers for exactly this reason).
250	export const MessageView = memo(function MessageView({ m, initial, hideWho, running, agent, agentLabel = "The agent", condensed, onAnswer, onCancelQueued, onClear, onReconnect }: { m: Msg; initial: boolean; hideWho: boolean; running?: boolean; agent?: string | null; agentLabel?: string; condensed?: boolean; onAnswer?: (askId: string, questions: AskQuestion[], answers: AskAnswers) => Promise<void> | undefined; onCancelQueued?: (pendingId: string) => void; onClear?: () => void; onReconnect?: () => void }) {
251	  if (m.role === "queued") {
252	    // A follow-up the user typed mid-turn, waiting its turn. Reads like a user
253	    // bubble but dimmed, tagged "Queued", with an × to drop it before it runs.
254	    const { text, attachments } = splitAttachments(m.content);
255	    return (
256	      <div className="msg user queued">
257	        <div className="who">
258	          <Avatar who="user" /> You
259	          <span className="badge queued-badge">queued</span>
260	          <span className="msg-meta-spacer" />
261	          <MessageTime value={m.createdAt} />
262	          {text && <CopyButton text={text} label="Copy message" className="msg-copy" />}
263	        </div>
264	        <div className="msg-body">
265	          {text && <Markdown>{text}</Markdown>}
266	          <AttachmentStrip items={attachments} />
267	          {onCancelQueued && <button className="queued-x" title="Remove from queue" aria-label="Remove from queue" onClick={() => onCancelQueued(m.id)}>{Icon.x()}</button>}
268	        </div>
269	      </div>
270	    );
271	  }
272	  if (m.role === "tool") {
273	    let data: ToolData;
274	    try { data = JSON.parse(m.content) as ToolData; } catch { data = { title: m.content }; }
275	    if (data.ask) {
276	      return <div className="msg msg-tool"><AskView data={data} agentLabel={agentLabel} onAnswer={async (answers) => { await onAnswer?.(data.ask?.id || m.toolId || "", data.ask?.questions ?? [], answers); }} /></div>;
277	    }
278	    return <div className="msg msg-tool"><ToolView data={data} condensed={condensed} /></div>;
279	  }
280	  if (m.role === "system") {
281	    if (m.content.startsWith(ARTIFACT_NOTICE_PREFIX)) {
282	      const notice = decodeArtifactNotice(m.content);
283	      if (notice) {
284	        return <ArtifactNoticeView notice={notice} createdAt={m.createdAt} />;
285	      }
286	    }
287	    // A context-overflow failure: render the warning line plus a one-click path
288	    // to /clear, which resets the poisoned session and starts a fresh window
289	    // (carrying a summary over). The notice string is matched verbatim — it's
290	    // the durable, reconnect-safe channel written by lib/runner.ts.
291	    if (m.content.includes(CONTEXT_OVERFLOW_NOTICE)) {
292	      return (
293	        <div className="msg system overflow">
294	          <div className="msg-body">
295	            {m.content}
296	            {onClear && (
297	              <div className="overflow-actions">
298	                <button className="btn btn-sm" onClick={onClear} disabled={running} title="Save a summary and start a fresh context window">
299	                  {Icon.clear()} Start fresh context
300	                </button>
301	              </div>
302	            )}
303	          </div>
304	        </div>
305	      );
306	    }
307	    // The agent's login died: same shape as the overflow case — the warning line
308	    // plus the one action that fixes it (Settings → Agents, where the connect
309	    // flow lives). Instance-wide, so the titlebar banner says it too; this is
310	    // the in-context copy for whoever is reading the failed task.
311	    if (m.content.includes(AUTH_EXPIRED_NOTICE)) {
312	      return (
313	        <div className="msg system overflow">
314	          <div className="msg-body">
315	            {m.content}
316	            {onReconnect && (
317	              <div className="overflow-actions">
318	                <button className="btn btn-sm" onClick={onReconnect} title={`Sign in to ${agentLabel} again`}>
319	                  {Icon.bolt()} Reconnect {agentLabel}
320	                </button>
321	              </div>
322	            )}
323	          </div>
324	        </div>
325	      );
326	    }
327	    // The agent's usage limit is spent: same shape as the two cases above, but
328	    // the only recovery is waiting for the reset (the error line above the
329	    // notice carries the reset time when the SDK reported one), so this renders
330	    // the notice styled like the others with no action button.
331	    if (m.content.includes(USAGE_LIMIT_NOTICE)) {
332	      return (
333	        <div className="msg system overflow">
334	          <div className="msg-body">{m.content}</div>
335	        </div>
336	      );
337	    }
338	    // Notes that already carry their own glyph (✓/ℹ — e.g. the "caught up to main"
